const skillPickers={};
let skillCatalogMemo=null,skillCatalogSignature='';
function skillCatalog(){const signature=jobs.map(j=>j.tags.join('|')).join('|');if(skillCatalogMemo&&signature===skillCatalogSignature)return skillCatalogMemo;skillCatalogSignature=signature;return skillCatalogMemo=[...new Set([...(window.NextworkCatalogs?.skills||[]),...ResumeEngine.skills,...jobs.flatMap(j=>j.tags),'C++','C#','Java','Go','Rust','Ruby','PHP','Swift','Kotlin','Vue','Angular','Svelte','Django','Flask','FastAPI','Express','MongoDB','Redis','Kubernetes','CI/CD','Linux','Bash','R','Power BI','Google Analytics','Google Ads','Email Marketing','A/B Testing','Brand Strategy','SEO','SEM','Product Management','Product Strategy','Sales','Customer Success','Operations','Financial Analysis','Business Analysis','Technical Writing','UX Writing','Copywriting','Social Media','Content Strategy','Interviews','Strategy','UI/UX Design'] )].sort((a,b)=>a.localeCompare(b))}
function canonicalSkills(value){const catalog=skillCatalog(),aliases={'js':'JavaScript','ts':'TypeScript','react.js':'React','nodejs':'Node.js','ux design':'UI/UX Design','data visualisation':'Data Visualization'};return [...new Set(String(value||'').split(',').map(s=>s.trim()).filter(Boolean).map(s=>catalog.find(c=>c.toLowerCase()===s.toLowerCase())||aliases[s.toLowerCase()]).filter(Boolean))]}
function skillSelectMarkup(prefix,label='Skills'){return `<div class="field skill-picker" id="${prefix}"><label for="${prefix}-input">${label}</label><div class="skill-picker-box"><div id="${prefix}-tags" class="skill-picker-tags"></div><input id="${prefix}-input" type="text" role="combobox" aria-label="Search skills" aria-autocomplete="list" aria-expanded="false" aria-controls="${prefix}-options" autocomplete="off" placeholder="Search and select skills…"><input type="hidden" name="skills" id="${prefix}-value"></div><div id="${prefix}-options" class="skill-options" role="listbox" hidden></div><small>Search thousands of skills, tools, and technologies. Choose a suggestion to keep spelling consistent. Press Enter to add, or Backspace to remove the last tag.</small></div>`}
function bindSkillSelect(prefix,value=''){skillPickers[prefix]={selected:canonicalSkills(value),index:0,matches:[]};const input=$('#'+prefix+'-input');input.oninput=()=>{skillPickers[prefix].index=0;paintSkillOptions(prefix)};input.onfocus=()=>paintSkillOptions(prefix);input.onkeydown=e=>{const state=skillPickers[prefix];if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();state.index=Math.max(0,Math.min(state.matches.length-1,state.index+(e.key==='ArrowDown'?1:-1)));paintSkillOptions(prefix,false)}if(e.key==='Enter'){e.preventDefault();if(state.matches[state.index])selectSkill(prefix,state.matches[state.index])}if(e.key==='Escape')hideSkills(prefix);if(e.key==='Backspace'&&!input.value&&state.selected.length){e.preventDefault();state.selected.pop();paintSkillTags(prefix)}};input.onblur=()=>setTimeout(()=>hideSkills(prefix),150);paintSkillTags(prefix)}
function paintSkillTags(prefix){const s=skillPickers[prefix];$('#'+prefix+'-tags').innerHTML=s.selected.map((v,i)=>`<span class="selected-skill">${esc(v)}<button type="button" aria-label="Remove ${esc(v)}" onclick="removeSkill('${prefix}',${i})">×</button></span>`).join('');$('#'+prefix+'-value').value=s.selected.join(', ')}
function paintSkillOptions(prefix,reset=true){const s=skillPickers[prefix],input=$('#'+prefix+'-input'),q=({'js':'javascript','ts':'typescript','nodejs':'node.js','reactjs':'react'}[input.value.toLowerCase().trim()]||input.value.toLowerCase().trim());const available=skillCatalog().filter(v=>!s.selected.includes(v));s.matches=typeof searchRank==='function'?searchRank(available,q,30):available.filter(v=>v.toLowerCase().includes(q)).slice(0,30);s.index=Math.max(0,Math.min(s.index,s.matches.length-1));const list=$('#'+prefix+'-options');list.hidden=false;input.setAttribute('aria-expanded','true');input.setAttribute('aria-activedescendant',prefix+'-option-'+s.index);list.innerHTML=s.matches.map((v,i)=>`<button type="button" role="option" id="${prefix}-option-${i}" aria-selected="${i===s.index}" class="${i===s.index?'active':''}" data-skill="${esc(v)}" onmousedown="event.preventDefault()" onclick="selectSkill('${prefix}',this.dataset.skill)">${esc(v)}</button>`).join('')||'<p>No matching skills. Try a broader term.</p>'}
function selectSkill(prefix,value){const s=skillPickers[prefix];if(!skillCatalog().includes(value)||s.selected.includes(value))return;if(s.selected.length>=20)return toast('Choose up to 20 skills.');s.selected.push(value);$('#'+prefix+'-input').value='';paintSkillTags(prefix);hideSkills(prefix);$('#'+prefix+'-input').focus()}
function removeSkill(prefix,index){skillPickers[prefix].selected.splice(index,1);paintSkillTags(prefix)}
function hideSkills(prefix){const el=$('#'+prefix+'-options');if(el)el.hidden=true;$('#'+prefix+'-input')?.setAttribute('aria-expanded','false');$('#'+prefix+'-input')?.removeAttribute?.('aria-activedescendant')}
